window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-153e172ad3a89b5f"]={"versions": [{"id": "FIG-153e172ad3a89b5f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (<code>ad Time Triggered Increased Inoperation</code>) im Kontext des AUTOSAR ECU State Managers (ECU-M, Classic Platform). Es spezifiziert den internen Ablauf des Algorithmus für TTII (Time Triggered Increased Inoperation) beim Aufwachen (<code>from WAKEUP</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten: <code>from WAKEUP</code>\n</li><li>Endknoten: <code>ActivityFinal</code>\n</li><li>Aktionen: <code>Decrement Divisor Counter</code>, <code>Get succeeding sleep mode</code>, <code>Preload divisor counter for new sleep mode</code>\n</li><li>Entscheidungsknoten: Verzweigung mit Bedingung <code>Divisor Counter &lt;= 1 ?</code> und Guards <code>[yes]</code> und <code>[no]</code>\n</li><li>Datenobjekte / Speicher: <code>Divisor Counter</code> (gekennzeichnet über Notiz als <code>static variable</code>)\n</li><li>Konfigurationsdaten: <code>«configuration data» ECUM_TTII_SUCCESSOR_LIST</code> und <code>«configuration data» ECUM_TTII_DIVISOR_LIST</code>, verknüpft über die Abhängigkeit <code>sleep mode names</code>\n</li><li>Kontroll- und Datenflüsse: Gestrichelte Pfeile zeigen Lese-/Schreibzugriffe der Aktionen auf <code>Divisor Counter</code> sowie Lesezugriffe auf die Konfigurationslisten. Durchgezogene Pfeile stellen den Kontrollfluss dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt aus der Wakeup-Phase (<code>from WAKEUP</code>) in die Aktion <code>Decrement Divisor Counter</code>. Die Aktion dekrementiert die statische Variable <code>Divisor Counter</code>.\n</li><li>Am Entscheidungsknoten wird geprüft: <code>Divisor Counter &lt;= 1 ?</code>.\n</li><li>Zweig <code>[no]</code>: Wenn die Bedingung nicht erfüllt ist, terminiert die TTII-Aktivität direkt im Knoten <code>ActivityFinal</code>.\n</li><li>Zweig <code>[yes]</code>: Wenn der Zähler 1 oder kleiner ist, folgt die Aktion <code>Get succeeding sleep mode</code>, welche den nächsten Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code> ermittelt.\n</li><li>Anschließend führt <code>Preload divisor counter for new sleep mode</code> unter Verwendung der ermittelten Schlafmodus-Parameter aus <code>ECUM_TTII_DIVISOR_LIST</code> das Vorbelegen der statischen Variable <code>Divisor Counter</code> durch.\n</li><li>Nach dem Vorbelegen endet die Aktivität im Knoten <code>ActivityFinal</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert verbindlich die Abarbeitungsreihenfolge und Zählerlogik für zeitgesteuert verlängerte Inaktivitätszyklen (TTII) im ECU State Manager. Implementierer müssen sicherstellen, dass <code>Divisor Counter</code> als persistente statische Variable gehalten wird. Vor dem Wechsel in tiefere Schlafmodi muss der Teilerzähler dekrementiert und erst bei Erreichen des Grenzwerts (&lt;= 1) der nächste Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code> geladen sowie der Zähler anhand von <code>ECUM_TTII_DIVISOR_LIST</code> neu initialisiert werden.</p>"}, {"id": "FIG-77592404cbab9bb1", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm im Kontext des AUTOSAR ECU State Managers (ECU-M, Classic Platform). Es spezifiziert den internen Ablauf des Algorithmus für TTII (Time Triggered Increased Inoperation) beim Aufwachen (<code>from WAKEUP</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten: <code>from WAKEUP</code>\n</li><li>Endknoten: <code>ActivityFinal</code>\n</li><li>Aktionen: <code>Decrement Divisor Counter</code>, <code>Get succeeding sleep mode</code>, <code>Preload divisor counter for new sleep mode</code>\n</li><li>Entscheidungsknoten: Verzweigung mit Bedingung <code>Divisor Counter &lt;= 1 ?</code> und Guards <code>[yes]</code> und <code>[no]</code>\n</li><li>Datenobjekte / Speicher: <code>Divisor Counter</code> (gekennzeichnet über Notiz als <code>static variable</code>)\n</li><li>Konfigurationsdaten: <code>«configuration data» ECUM_TTII_SUCCESSOR_LIST</code> und <code>«configuration data» ECUM_TTII_DIVISOR_LIST</code>, verknüpft über die Abhängigkeit <code>sleep mode names</code>\n</li><li>Kontroll- und Datenflüsse: Gestrichelte Pfeile zeigen Lese-/Schreibzugriffe der Aktionen auf <code>Divisor Counter</code> sowie Lesezugriffe auf die Konfigurationslisten. Durchgezogene Pfeile stellen den Kontrollfluss dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt aus der Wakeup-Phase (<code>from WAKEUP</code>) in die Aktion <code>Decrement Divisor Counter</code>. Die Aktion dekrementiert die statische Variable <code>Divisor Counter</code>.\n</li><li>Am Entscheidungsknoten wird geprüft: <code>Divisor Counter &lt;= 1 ?</code>.\n</li><li>Zweig <code>[no]</code>: Wenn die Bedingung nicht erfüllt ist, terminiert die TTII-Aktivität direkt im Knoten <code>ActivityFinal</code>.\n</li><li>Zweig <code>[yes]</code>: Wenn der Zähler 1 oder kleiner ist, folgt die Aktion <code>Get succeeding sleep mode</code>, welche den nächsten Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code> ermittelt.\n</li><li>Anschließend führt <code>Preload divisor counter for new sleep mode</code> unter Verwendung der ermittelten Schlafmodus-Parameter aus <code>ECUM_TTII_DIVISOR_LIST</code> das Vorbelegen der statischen Variable <code>Divisor Counter</code> durch.\n</li><li>Nach dem Vorbelegen endet die Aktivität im Knoten <code>ActivityFinal</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert verbindlich die Abarbeitungsreihenfolge und Zählerlogik für zeitgesteuert verlängerte Inaktivitätszyklen (TTII) im ECU State Manager. Implementierer müssen sicherstellen, dass <code>Divisor Counter</code> als persistente statische Variable gehalten wird. Vor dem Wechsel in tiefere Schlafmodi muss der Teilerzähler dekrementiert und erst bei Erreichen des Grenzwerts (&lt;= 1) der nächste Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code> geladen sowie der Zähler anhand von <code>ECUM_TTII_DIVISOR_LIST</code> neu initialisiert werden.</p>"}, {"id": "FIG-347eefd7bb6dbb04", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm im Kontext des AUTOSAR ECU State Managers (ECU-M, Classic Platform). Es spezifiziert den internen Ablauf des Algorithmus für TTII (Time Triggered Increased Inoperation) beim Aufwachen (<code>from WAKEUP</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten: <code>from WAKEUP</code>\n</li><li>Endknoten: <code>ActivityFinal</code>\n</li><li>Aktionen: <code>Decrement Divisor Counter</code>, <code>Get succeeding sleep mode</code>, <code>Preload divisor counter for new sleep mode</code>\n</li><li>Entscheidungsknoten: Verzweigung mit Bedingung <code>Divisor Counter &lt;= 1 ?</code> und Guards <code>[yes]</code> und <code>[no]</code>\n</li><li>Datenobjekte / Speicher: <code>Divisor Counter</code> (gekennzeichnet über Notiz als <code>static variable</code>)\n</li><li>Konfigurationsdaten: <code>«configuration data» ECUM_TTII_SUCCESSOR_LIST</code> und <code>«configuration data» ECUM_TTII_DIVISOR_LIST</code>, verknüpft über die Abhängigkeit <code>sleep mode names</code>\n</li><li>Kontroll- und Datenflüsse: Gestrichelte Pfeile zeigen Lese-/Schreibzugriffe der Aktionen auf <code>Divisor Counter</code> sowie Lesezugriffe auf die Konfigurationslisten. Durchgezogene Pfeile stellen den Kontrollfluss dar.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt aus der Wakeup-Phase (<code>from WAKEUP</code>) in die Aktion <code>Decrement Divisor Counter</code>. Die Aktion dekrementiert die statische Variable <code>Divisor Counter</code>.\n</li><li>Am Entscheidungsknoten wird geprüft: <code>Divisor Counter &lt;= 1 ?</code>.\n</li><li>Zweig <code>[no]</code>: Wenn die Bedingung nicht erfüllt ist, terminiert die TTII-Aktivität direkt im Knoten <code>ActivityFinal</code>.\n</li><li>Zweig <code>[yes]</code>: Wenn der Zähler 1 oder kleiner ist, folgt die Aktion <code>Get succeeding sleep mode</code>, welche den nächsten Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code> ermittelt.\n</li><li>Anschließend führt <code>Preload divisor counter for new sleep mode</code> unter Verwendung der ermittelten Schlafmodus-Parameter aus <code>ECUM_TTII_DIVISOR_LIST</code> das Vorbelegen der statischen Variable <code>Divisor Counter</code> durch.\n</li><li>Nach dem Vorbelegen endet die Aktivität im Knoten <code>ActivityFinal</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert verbindlich die Abarbeitungsreihenfolge und Zählerlogik für zeitgesteuert verlängerte Inaktivitätszyklen (TTII) im ECU State Manager. Implementierer müssen sicherstellen, dass <code>Divisor Counter</code> als persistente statische Variable gehalten wird. Vor dem Wechsel in tiefere Schlafmodi muss der Teilerzähler dekrementiert und erst bei Erreichen des Grenzwerts (&lt;= 1) der nächste Schlafmodus aus <code>ECUM_TTII_SUCCESSOR_LIST</code> geladen sowie der Zähler anhand von <code>ECUM_TTII_DIVISOR_LIST</code> neu initialisiert werden.</p>"}], "trans": [{"from": "FIG-153e172ad3a89b5f", "to": "FIG-77592404cbab9bb1", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Diagrammrahmen mit Kopfzeile <code>ad Time Triggered Increased Inoperation</code> entfernt.\n</li><li>Bildbeschnitt an den Rändern verengt; Beschriftungen links (<code>Divisor Counter &lt;= 1 ?</code>) und unten (<code>ActivityFinal</code>) am linken Rand leicht angeschnitten.\n</li><li>Dezente Anpassung der Farbgebung bzw. Schattierung der Aktionselemente (wärmerer Ton, Schattierungsstil aktualisiert).\n</li></ul>"}, {"from": "FIG-77592404cbab9bb1", "to": "FIG-347eefd7bb6dbb04", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
